with filtered as (select *, date_add(launch_date, 20) as launch_date_plus_20d from products where brand is not null), latest_match as (select s.*, top1.inventory_quantity from filtered s join lateral (select c.quantity as inventory_quantity from inventory c where c.product_id = s.id order by c.quantity desc, c.id desc limit 1) top1 on true), enriched as (select *, ntile(10) over (partition by brand order by price, id) as price_bucket, lead(cost, 1) over (order by price, id) as next_cost, avg(stock_qty) over (partition by category order by launch_date_plus_20d, id rows between 2 preceding and current row) as stock_qty_avg_2, sum(stock_qty) over (partition by brand, category order by stock_qty, id rows between unbounded preceding and current row) as cumulative_stock_qty from latest_match), with_dims as (select a.*, p.country from enriched a left join suppliers p on a.supplier_id = p.id) select id, category, brand, cost, stock_qty, launch_date, supplier_id, launch_date_plus_20d, inventory_quantity from with_dims order by supplier_id desc;
